EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d VALUES(N''a'',N''s'',N''S'',1,1,1,1,NULL,NULL),(N''b'',N''s'',N''different'',1,2,2,2,NULL,NULL); EXEC viz.LineChart @d;',51001,N'Conflicting series metadata';
EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d VALUES(N''a'',N''s'',N''S'',1,1,0.1,1,NULL,NULL); EXEC viz.LineChart @d,@XKind=''time'',@XFormat=''utc-time'';',51002,N'Fractional UTC millisecond rejected';
EXEC #Error N'DECLARE @d viz.XY_v1; EXEC viz.LineChart @d,@XKind=''time'';',51000,N'Time format must be explicit';
EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d VALUES(N''a'',N''s'',N''S'',1,1,1,1,-1,NULL); EXEC viz.BubbleChart @d;',51001,N'Negative area rejected';
EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d VALUES(N''a'',N''s'',N''S'',1,1,0,1,1,NULL); EXEC viz.BubbleChart @d,@XScale=''log'';',51002,N'Nonpositive log X rejected';
EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d SELECT CONVERT(nvarchar(10),N),N''s'',N''S'',1,N,N,1,1,NULL FROM viz.Numbers(201); EXEC viz.BubbleChart @d;',51004,N'No silent bubble downsampling';
EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d SELECT CONVERT(nvarchar(10),N),N''s'',N''S'',1,N,N,1,1,NULL FROM viz.Numbers(5001); EXEC viz.LineChart @d;',51004,N'No silent line downsampling';
EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d VALUES(N''a'',N''s'',N''S'',1,1,1e16,1,1,NULL); EXEC viz.LineChart @d;',51004,N'Input numeric budget';
EXEC #Error N'DECLARE @d viz.XY_v1; EXEC viz.LineChart @d,@XMin=0,@XMax=0.000000001;',51000,N'Indistinguishable ticks fail explicitly';
