EXEC #Error N'DECLARE @d viz.XY_v1; INSERT @d VALUES(N''a'',N''s'',N''S'',1,1,1,1,1e-100,NULL),(N''b'',N''s'',N''S'',1,2,2,2,1e15,NULL); EXEC viz.BubbleChart @d;',51004,N'Unrepresentable positive bubble radius is explicit';
EXEC #Error N'DECLARE @d viz.CategoryValue_v1; INSERT @d VALUES(N''a'',N''a'',N''A'',1,N''s'',N''S'',1,1e-100,NULL); EXEC viz.BarChart @d,@ValueMin=0,@ValueMax=1e15;',51004,N'Unrepresentable nonzero bar width is explicit';
